```rust
fn knife_turn() -> GameState {
    jackioh_cards::register_all();
    scenario(json!({
        "seed": "r4608000", "turn": 5, "active": "p1",
        "p1": { "hand": [JUGGLER, DEFENDER, GUY_ATT], "mana": 2,
                "library": ["core-008", "core-011", "core-008", "core-011", "core-008"] },
        "p2": { "health": 1, "field": ["core-001"], "library": ["core-008", "core-011", "core-008"] },
    }))
    .state()
    .clone()
}

fn hand_id(state: &GameState, def: &str) -> String {
    state.players[AI].hand.iter().find(|card| card.def_id == def).map(|card| card.id.clone())
        .unwrap_or_else(|| panic!("{def} is not in hand"))
}

fn plays(state: &GameState, action: &ActionBody, def: &str) -> bool {
    let id = hand_id(state, def);
    matches!(action, ActionBody::Play { instance_id, .. } if *instance_id == id)
}

fn play_of(state: &GameState, def: &str) -> ActionBody {
    candidate_actions(state, AI, Prices::NONE).into_iter().find(|action| plays(state, action, def))
        .unwrap_or_else(|| panic!("{def} is not a candidate"))
}

fn won_floor() -> f64 {
    AI_EVAL.win * AI_WON_SCORE_SHARE
}

struct Run { seed: String, gamble: Vec<f64>, board: Vec<f64>, decision: Decision }

impl Run {
    fn won(&self) -> Vec<bool> { self.gamble.iter().map(|score| *score > won_floor()).collect() }
    fn clean(&self) -> bool { self.board.iter().all(|score| *score <= won_floor()) }
}

fn runs() -> Vec<Run> {
    let state = knife_turn();
    let public = redact(&state, AI);
    (0..SEEDS).map(|n| {
        let seed = format!("r4608000-{n}");
        with_pool_shift(0, || {
            let mut rng = create_rng(&seed, 0);
            let worlds: Vec<GameState> =
                (0..AI_BUDGET.determinizations).map(|_| det(&public, AI, &mut rng)).collect();
            let first = worlds.first().expect("a world");
            let juggler = play_of(first, JUGGLER);
            let gamble = vec![juggler.clone(), play_of(&act(first, AI, &juggler), DEFENDER)];
            let board = vec![play_of(first, GUY_ATT)];
            let score = |line: &[ActionBody], world: &GameState| {
                let counter = create_node_counter(AI_BUDGET.nodes, None);
                let hidden = hidden_card_ids(world, AI);
                replay_line(world, AI, line, &counter, Some(&hidden), Prices::NONE, ReplayFill::OFF)
                    .unwrap_or_else(|| panic!("{seed}: the counter ran out")).score
            };
            let decision = decide(&state, AI, &mut ai_options(&seed, AI_BUDGET))
                .unwrap_or_else(|| panic!("{seed}: no decision"));
            Run {
                gamble: worlds.iter().map(|world| score(&gamble, world)).collect(),
                board: worlds.iter().map(|world| score(&board, world)).collect(),
                seed: seed.clone(),
                decision,
            }
        })
    }).collect()
}
```

- `r4608000_the_ai_makes_the_board_play_when_only_its_searched_world_rolls_lethal`: over `runs()` filtered by `clean()`:
  - on each lone seed (`run.won() == [true, false, false]`), assert `run.board[w] > run.gamble[w]` for `w in 1..3`, `decision.stats.worlds_scored == 3`, and `plays(&state, &decision.action, GUY_ATT)`;
  - on each none seed, assert it plays Guy Att too;
  - at the end, assert `lone >= 5 && none >= 5`;
  - put the seed in every message.
- `r4608000_the_ai_still_goes_for_a_lethal_two_of_three_worlds_roll`: over the same seeds, skip those whose world 0 did not win or whose other worlds won nowhere:
  - every remaining seed plays the Juggler;
  - with exactly one other world won, `reason == DecisionReason::Search` and `stats.score > won_floor()`;
  - with both other worlds won, `reason == DecisionReason::Lethal`;
  - at the end, assert `two >= 5 && three >= 3`.

